import math


def dpo_loss(policy_w, policy_l, ref_w, ref_l, beta=0.1):
    margin = beta * ((policy_w - ref_w) - (policy_l - ref_l))
    if margin >= 0:
        return math.log1p(math.exp(-margin))
    return -margin + math.log1p(math.exp(margin))

def sft_loss(token_logprobs, roles):
    losses = [-lp for lp, role in zip(token_logprobs, roles) if role == "assistant"]
    if not losses:
        raise ValueError("no assistant tokens")
    return sum(losses) / len(losses)
